def get_cu_num_custom_op() -> int:
    cu_num = int(os.getenv("CU_NUM", "0"))
    if cu_num == 0:
        use_existing = os.getenv("SMG_SG2_CU_EXISTING_RUNTIME") == "1"
        query_source = "rocminfo"
        if use_existing:
            try:
                import torch

                if torch.version.hip is None:
                    raise RuntimeError("existing HIP runtime required")
                if torch.cuda.is_initialized():
                    query_source = "existing-hip-runtime"
                    visible_count = torch.cuda.device_count()
                    logical_device = torch.cuda.current_device()
                    if type(visible_count) is not int or visible_count < 1:
                        raise RuntimeError("no process-visible HIP devices")
                    if type(logical_device) is not int or not 0 <= logical_device < visible_count:
                        raise RuntimeError("invalid current logical HIP device")
                    gpu_compute_units = [
                        torch.cuda.get_device_properties(i).multi_processor_count
                        for i in range(visible_count)
                    ]
                    if any(type(cu) is not int or cu <= 0 for cu in gpu_compute_units):
                        raise RuntimeError("invalid HIP compute-unit property")
                    if len(set(gpu_compute_units)) != 1:
                        raise RuntimeError("heterogeneous process-visible HIP compute units")
                    _smg_sg2_cu(__name__, __file__, locals())
                    return gpu_compute_units[logical_device]
            except Exception as e:  # No subprocess fallback after a runtime property failure.
                _smg_sg2_cu(__name__, __file__, locals())
                raise RuntimeError(f"Get GPU Compute Unit from existing HIP runtime failed {e!s}") from e
        try:
            rocminfo = executable_path("rocminfo")
            result = subprocess.run(
                [rocminfo], capture_output=True, text=True, check=False
            )
            if use_existing and result.returncode != 0:
                raise RuntimeError(f"rocminfo returned {result.returncode}")
            output = result.stdout
            devices = re.split(r"Agent\s*\d+", output)
            gpu_compute_units = []
            for device in devices:
                for line in device.split("\n"):
                    if "Device Type" in line and line.find("GPU") != -1:
                        match = re.search(r"Compute Unit\s*:\s*(\d+)", device)
                        if match:
                            gpu_compute_units.append(int(match.group(1)))
                        break
        except Exception as e:  # noqa: BLE001  blanket catch is intentional here
            _smg_sg2_cu(__name__, __file__, locals())
            raise RuntimeError(f"Get GPU Compute Unit from rocminfo failed {e!s}")
        _smg_sg2_cu(__name__, __file__, locals())
        if use_existing and (not gpu_compute_units or any(cu <= 0 for cu in gpu_compute_units)):
            raise RuntimeError("rocminfo returned no positive GPU compute units")
        assert len(set(gpu_compute_units)) == 1
        cu_num = gpu_compute_units[0]
    return cu_num

